const questions: BankQuestion[] = [
  {"id": "history-art-culture-1", "question": "Kathakali, the classical dance-drama, belongs to which state?", "options": ["Tamil Nadu", "Kerala", "Karnataka", "Odisha"], "answer": 1, "explanation": "Kathakali is from Kerala. Bharatanatyam is from Tamil Nadu and Odissi from Odisha.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-2", "question": "The Sun Temple at Konark is in:", "options": ["Odisha", "West Bengal", "Gujarat", "Andhra Pradesh"], "answer": 0, "explanation": "The Konark Sun Temple, built by the Eastern Ganga king Narasimhadeva I in the 13th century, stands on the Odisha coast. Modhera in Gujarat has another Sun temple.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-art-culture-3", "question": "The Ajanta caves, famous for their Buddhist wall paintings, are in:", "options": ["Madhya Pradesh", "Karnataka", "Maharashtra", "Bihar"], "answer": 2, "explanation": "Ajanta is in Aurangabad (Chhatrapati Sambhajinagar) district, Maharashtra, as is Ellora.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-4", "question": "Bihu is the main festival of:", "options": ["Assam", "Punjab", "Kerala", "Tamil Nadu"], "answer": 0, "explanation": "Bihu, celebrated three times a year (Rongali, Kongali and Bhogali), is Assam’s main festival.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-art-culture-5", "question": "Kuchipudi takes its name from a village in:", "options": ["Tamil Nadu", "Karnataka", "Odisha", "Andhra Pradesh"], "answer": 3, "explanation": "Kuchipudi village is in Krishna district of Andhra Pradesh, where the Bhagavata Mela tradition of the dance grew.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-6", "question": "The Sattriya dance grew in the Vaishnava monasteries (sattras) of:", "options": ["Manipur", "Assam", "Odisha", "Tripura"], "answer": 1, "explanation": "Sattriya developed in the sattras of Assam from the 15th–16th century; the Sangeet Natak Akademi recognised it as classical in 2000.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-art-culture-7", "question": "Madhubani (Mithila) painting is a folk art of:", "options": ["Bihar", "Odisha", "Rajasthan", "Gujarat"], "answer": 0, "explanation": "Madhubani painting comes from the Mithila region of Bihar and has a GI tag.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-art-culture-8", "question": "The temples of Khajuraho were built by the:", "options": ["Paramaras", "Chandelas", "Solankis", "Gahadavalas"], "answer": 1, "explanation": "The Chandela rulers of Bundelkhand built the Khajuraho temples between about 950 and 1050.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-9", "question": "A temple with a stepped pyramidal tower (vimana) over the sanctum and tall gateway towers (gopurams) belongs to which style?", "options": ["Nagara", "Vesara", "Dravida", "Kalinga"], "answer": 2, "explanation": "The Dravida style of south India has a vimana over the sanctum and gopurams at the entrances; the Nagara style has a curvilinear shikhara.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-art-culture-10", "question": "Warli painting, made with white paste on mud walls, is the art of a tribe of:", "options": ["Maharashtra", "Jharkhand", "Chhattisgarh", "Madhya Pradesh"], "answer": 0, "explanation": "The Warli tribe lives in the Thane and Palghar region of Maharashtra. Gond painting comes from Madhya Pradesh.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-11", "question": "Which of the following is NOT one of the Trinity of Carnatic music?", "options": ["Tyagaraja", "Muthuswami Dikshitar", "Syama Sastri", "Purandaradasa"], "answer": 3, "explanation": "The Trinity are Tyagaraja, Muthuswami Dikshitar and Syama Sastri (18th–19th century). Purandaradasa (16th century) is called the father of Carnatic music.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-art-culture-12", "question": "The Hornbill Festival is held every December in:", "options": ["Mizoram", "Nagaland", "Arunachal Pradesh", "Manipur"], "answer": 1, "explanation": "Nagaland holds the Hornbill Festival at Kisama near Kohima from 1 to 10 December.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-art-culture-13", "question": "The Vesara style of temple architecture, a blend of Nagara and Dravida features, is chiefly associated with:", "options": ["The Pallavas", "The Chalukyas of Kalyani and the Hoysalas", "The Cholas", "The Eastern Gangas"], "answer": 1, "explanation": "Vesara flourished in the Deccan under the later Chalukyas and the Hoysalas. The Pallavas and Cholas built in the Dravida style, and the Gangas of Odisha in the Kalinga variant of Nagara.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-14", "question": "The rock-cut Kailasa temple at Ellora was carved under:", "options": ["Rashtrakuta king Krishna I", "Chalukya king Pulakeshin II", "Pallava king Mahendravarman I", "Rashtrakuta king Amoghavarsha"], "answer": 0, "explanation": "The monolithic Kailasa temple (cave 16) was carved in the reign of Krishna I in the 8th century.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-15", "question": "The Shore Temple at Mamallapuram was built by:", "options": ["Mahendravarman I", "Narasimhavarman I", "Narasimhavarman II (Rajasimha)", "Nandivarman II"], "answer": 2, "explanation": "Narasimhavarman II (Rajasimha) built the structural Shore Temple around 700. Narasimhavarman I (Mamalla) is linked with the rock-cut rathas.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-16", "question": "Pattachitra, painting on cloth depicting the Jagannath cult and epic stories, is chiefly associated with:", "options": ["Odisha", "Rajasthan", "Kerala", "Telangana"], "answer": 0, "explanation": "Pattachitra is the traditional cloth painting of Odisha, centred on Puri and the village of Raghurajpur.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-art-culture-17", "question": "Kalamkari, hand-painted or block-printed textile art, is chiefly associated with Srikalahasti and Machilipatnam in:", "options": ["Tamil Nadu", "Andhra Pradesh", "Gujarat", "West Bengal"], "answer": 1, "explanation": "Srikalahasti (pen-drawn) and Machilipatnam (block-printed) Kalamkari are from Andhra Pradesh.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-art-culture-18", "question": "Kalakshetra, the institution that helped revive Bharatanatyam in the 20th century, was founded in 1936 by:", "options": ["Rukmini Devi Arundale", "Balasaraswati", "Mrinalini Sarabhai", "Yamini Krishnamurthy"], "answer": 0, "explanation": "Rukmini Devi Arundale founded Kalakshetra at Adyar, Madras, in 1936. Mrinalini Sarabhai founded Darpana in Ahmedabad.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-19", "question": "How many classical dance forms are recognised by the Sangeet Natak Akademi?", "options": ["Six", "Seven", "Eight", "Nine"], "answer": 2, "explanation": "The Akademi recognises eight: Bharatanatyam, Kathak, Kathakali, Kuchipudi, Manipuri, Mohiniyattam, Odissi and Sattriya. The Ministry of Culture also counts Chhau, making nine on its list.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-20", "question": "Which is regarded as the oldest surviving form of Hindustani classical vocal music, kept alive by the Dagar family?", "options": ["Khayal", "Thumri", "Tappa", "Dhrupad"], "answer": 3, "explanation": "Dhrupad, rooted in temple music and patronised at Gwalior and the Mughal court, is the oldest; Khayal, Thumri and Tappa developed later.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-art-culture-21", "question": "The Gita Govinda, whose songs are central to the Odissi dance repertoire, was composed by:", "options": ["Jayadeva", "Vidyapati", "Chandidas", "Kalidasa"], "answer": 0, "explanation": "Jayadeva, a 12th-century poet, wrote the Gita Govinda in Sanskrit; its ashtapadis are sung in Odissi performances.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-22", "question": "Durga Puja in Kolkata was added to UNESCO’s list of the Intangible Cultural Heritage of Humanity in:", "options": ["2016", "2019", "2021", "2023"], "answer": 2, "explanation": "Durga Puja in Kolkata was inscribed in December 2021. Garba of Gujarat followed in 2023, and Yoga in 2016.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-23", "question": "Rani-ki-Vav, the stepwell at Patan inscribed as a World Heritage Site in 2014, was built by:", "options": ["Rani Rudrama Devi of the Kakatiyas", "Queen Udayamati in memory of the Chaulukya king Bhima I", "Rani Durgavati of Gondwana", "Queen Ahilyabai Holkar"], "answer": 1, "explanation": "Queen Udayamati built Rani-ki-Vav in the 11th century in memory of her husband Bhima I of the Chaulukya (Solanki) dynasty.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-24", "question": "The Vimala Vasahi, the oldest of the Dilwara temples at Mount Abu, was built in 1031 by:", "options": ["Vastupala and Tejapala", "Vimal Shah, a minister of the Chaulukya king Bhima I", "Rana Kumbha", "Kumarapala"], "answer": 1, "explanation": "Vimal Shah built the Vimala Vasahi, dedicated to Adinatha. The Luna Vasahi was built in 1230 by the brothers Vastupala and Tejapala.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-25", "question": "Match the classical dance with its state: A. Mohiniyattam B. Kuchipudi C. Sattriya D. Odissi — 1. Assam 2. Odisha 3. Kerala 4. Andhra Pradesh", "options": ["A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-2, D-1"], "answer": 0, "explanation": "Mohiniyattam – Kerala; Kuchipudi – Andhra Pradesh; Sattriya – Assam; Odissi – Odisha.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-26", "question": "How many of these statements about Chhau dance are correct? I. Its three styles are Purulia, Seraikela and Mayurbhanj. II. Mayurbhanj Chhau is performed without masks. III. It was inscribed on UNESCO’s intangible heritage list in 2010. IV. It is one of the eight classical dances recognised by the Sangeet Natak Akademi.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Chhau is not among the Akademi’s eight classical dances, though the Ministry of Culture lists it.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-27", "question": "Arrange these monuments by when they were built: 1. Kailasa temple, Ellora 2. Core of the Great Stupa, Sanchi 3. Qutb Minar (begun) 4. Kandariya Mahadeva temple, Khajuraho", "options": ["2-1-3-4", "2-4-1-3", "1-2-4-3", "2-1-4-3"], "answer": 3, "explanation": "Sanchi stupa core under Ashoka (3rd century BCE), Kailasa (8th century), Kandariya Mahadeva (about 1030), Qutb Minar begun by Aibak (about 1199).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-28", "question": "Which pair of painting school and region is NOT correctly matched?", "options": ["Kangra – Himachal Pradesh", "Kalighat – West Bengal", "Basohli – Jammu and Kashmir", "Kishangarh – Gujarat"], "answer": 3, "explanation": "Kishangarh, famous for the Bani Thani portrait, is a Rajasthani school. The other three pairs are correct.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-29", "question": "How many of these are on UNESCO’s list of the Intangible Cultural Heritage of Humanity? Kumbh Mela, Yoga, Garba of Gujarat, Ramlila", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four: Ramlila (2008), Yoga (2016), Kumbh Mela (2017) and Garba (2023).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-30", "question": "Assertion (A): Gandhara art shows strong Greco-Roman influence. Reason (R): It developed in the north-west, a region in long contact with Hellenistic and Roman culture.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: Gandhara’s position on the routes linking India with the Hellenistic and Roman world gave its Buddha images their wavy hair and toga-like robes.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-31", "question": "Assertion (A): The temples of Khajuraho are built in the Nagara style. Reason (R): They were built by the Pallava rulers.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 2, "explanation": "A is true: Khajuraho temples have curvilinear shikharas of the Nagara style. R is false: they were built by the Chandelas; the Pallavas ruled in Tamil Nadu.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-32", "question": "Which pair of musician and instrument is NOT correctly matched?", "options": ["Bismillah Khan – Shehnai", "Hariprasad Chaurasia – Flute", "Zakir Hussain – Tabla", "Amjad Ali Khan – Santoor"], "answer": 3, "explanation": "Amjad Ali Khan plays the sarod; the santoor is associated with Shivkumar Sharma.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-33", "question": "Arrange these works in chronological order: 1. Kalhana’s Rajatarangini 2. Bihari’s Satsai 3. Kalidasa’s Abhijnanashakuntalam 4. Banabhatta’s Harshacharita", "options": ["3-4-1-2", "4-3-1-2", "3-1-4-2", "3-4-2-1"], "answer": 0, "explanation": "Kalidasa (Gupta age, about 4th–5th century), Banabhatta (7th century, court of Harsha), Kalhana (1148–49), Bihari’s Satsai (17th century).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-34", "question": "How many of these statements about Hindu temple architecture are correct? I. The garbhagriha houses the main deity. II. The amalaka is the entrance gateway of a Nagara temple. III. The shikhara is typical of the Nagara style and the vimana of the Dravida style. IV. The gopuram is the main tower over the sanctum of a Dravida temple.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. The amalaka is the ribbed stone disc on top of a Nagara shikhara, and the gopuram is the gateway tower; the tower over the sanctum is the vimana.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-35", "question": "Match the festival with its state: A. Chapchar Kut B. Wangala C. Nuakhai D. Losoong — 1. Meghalaya 2. Mizoram 3. Sikkim 4. Odisha", "options": ["A-2, B-1, C-3, D-4", "A-2, B-1, C-4, D-3", "A-1, B-2, C-4, D-3", "A-2, B-4, C-1, D-3"], "answer": 1, "explanation": "Chapchar Kut – Mizoram; Wangala (Garo harvest festival) – Meghalaya; Nuakhai (new rice) – Odisha; Losoong (Bhutia new year) – Sikkim.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "history-art-culture-36", "question": "Which one of the following is NOT a UNESCO World Heritage Site?", "options": ["Ramappa Temple, Telangana", "Dholavira, Gujarat", "Santiniketan, West Bengal", "Golden Temple, Amritsar"], "answer": 3, "explanation": "Ramappa and Dholavira were inscribed in 2021 and Santiniketan in 2023. The Golden Temple is not on the World Heritage List.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-37", "question": "How many of these statements are correct? I. Raga and tala are basic elements of both Hindustani and Carnatic music. II. Tyagaraja composed mainly in Kannada. III. Purandaradasa is called the father (Pitamaha) of Carnatic music. IV. Thumri is a form of Carnatic music.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. Tyagaraja composed mainly in Telugu, and Thumri is a light-classical form of Hindustani music.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-38", "question": "Assertion (A): Kathakali performers wear elaborate face make-up and costumes. Reason (R): Kathakali originated in Kerala.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 1, "explanation": "Both are true, but R does not explain A: the make-up identifies character types (pacha for noble heroes, kathi for villains), which has nothing to do with the region of origin.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-39", "question": "Arrange these temples by when they were built: 1. Chennakeshava temple, Belur 2. Brihadeeswara temple, Thanjavur 3. Sun Temple, Konark 4. Vittala temple, Hampi", "options": ["2-1-4-3", "1-2-3-4", "2-1-3-4", "2-3-1-4"], "answer": 2, "explanation": "Brihadeeswara completed 1010 (Rajaraja I), Chennakeshava 1117 (Hoysala Vishnuvardhana), Konark about 1250 (Narasimhadeva I), Vittala temple 15th–16th century (Vijayanagara).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-40", "question": "Which pair of temple and the dynasty that built it is NOT correctly matched?", "options": ["Brihadeeswara, Thanjavur – Cholas", "Kailasa, Ellora – Rashtrakutas", "Shore Temple, Mamallapuram – Pallavas", "Lingaraja, Bhubaneswar – Chandelas"], "answer": 3, "explanation": "The Lingaraja temple was built by the Somavamshi kings of Odisha in the 11th century; the Chandelas built Khajuraho.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-41", "question": "Bharatanatyam, one of the oldest classical dance forms, developed in:", "options": ["Kerala", "Tamil Nadu", "Karnataka", "Odisha"], "answer": 1, "explanation": "Bharatanatyam grew from the temple dance (sadir) of Tamil Nadu. Kerala's classical dances are Kathakali and Mohiniyattam.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "history-art-culture-42", "question": "Bhangra is a folk dance of:", "options": ["Haryana", "Gujarat", "Punjab", "Rajasthan"], "answer": 2, "explanation": "Bhangra is the harvest dance of Punjab, performed to the dhol around Baisakhi. Giddha is the women's folk dance of the same region.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "history-art-culture-43", "question": "The Taj Mahal at Agra was built by:", "options": ["Akbar", "Jahangir", "Aurangzeb", "Shah Jahan"], "answer": 3, "explanation": "Shah Jahan built the Taj Mahal (1632–53) as the tomb of his wife Mumtaz Mahal. It was inscribed as a World Heritage Site in 1983.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "history-art-culture-44", "question": "The Kumbh Mela is held in rotation at Prayagraj, Haridwar, Ujjain and:", "options": ["Nashik", "Varanasi", "Puri", "Mathura"], "answer": 0, "explanation": "The four Kumbh sites are Prayagraj (Ganga–Yamuna), Haridwar (Ganga), Ujjain (Shipra) and Nashik (Godavari).", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-45", "question": "Pongal, the harvest festival, is mainly celebrated in:", "options": ["Punjab", "Tamil Nadu", "Assam", "Gujarat"], "answer": 1, "explanation": "Pongal is Tamil Nadu's four-day harvest festival in mid-January, at the same time as Makar Sankranti, Lohri and Magh Bihu elsewhere.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "history-art-culture-46", "question": "The Ras Lila, depicting Krishna's dance with the gopis, is a central theme of which classical dance?", "options": ["Kathak", "Manipuri", "Kuchipudi", "Sattriya"], "answer": 1, "explanation": "Manipuri dance, with its gentle movements and Vaishnava themes, is famous for its Ras Lila. Kathak also uses Krishna stories, but the Ras Lila is the signature of Manipuri.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-47", "question": "Gond painting, made of dots and fine lines, is a tribal art chiefly of:", "options": ["Madhya Pradesh", "Bihar", "Maharashtra", "Odisha"], "answer": 0, "explanation": "Gond art comes from the Gond tribe of Madhya Pradesh; Jangarh Singh Shyam made it widely known. Warli is from Maharashtra and Madhubani from Bihar.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-48", "question": "Phad painting, long cloth scrolls narrating the lives of folk deities such as Pabuji and Devnarayan, belongs to:", "options": ["Gujarat", "Rajasthan", "Odisha", "Andhra Pradesh"], "answer": 1, "explanation": "Phad is a scroll painting of Rajasthan (Shahpura, Bhilwara), carried by bhopa priests who sing the story as they show the scroll.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-art-culture-49", "question": "Tanjore painting, known for its rich colours and use of gold foil and semi-precious stones, is from:", "options": ["Kerala", "Karnataka", "Tamil Nadu", "Andhra Pradesh"], "answer": 2, "explanation": "Thanjavur painting flourished under the Marathas of Thanjavur in Tamil Nadu. Mysore painting of Karnataka uses gesso work more delicately.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-50", "question": "Akbar built the Buland Darwaza at Fatehpur Sikri to commemorate his victory over:", "options": ["Bengal", "Gujarat", "Chittor", "Kabul"], "answer": 1, "explanation": "The Buland Darwaza commemorates Akbar's conquest of Gujarat (1573). It is the main gateway of the Jama Masjid at Fatehpur Sikri.", "difficulty": "moderate", "source": "RRB NTPC · SSC CHSL"},
  {"id": "history-art-culture-51", "question": "The 'kriti' is a composition form chiefly associated with:", "options": ["Hindustani music", "Carnatic music", "Sufi qawwali", "Rabindra Sangeet"], "answer": 1, "explanation": "The kriti, with its pallavi, anupallavi and charanam, is the main concert form of Carnatic music, perfected by the Trinity. Khayal and dhrupad are Hindustani forms.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-52", "question": "The Elephanta caves, known for the colossal three-headed Sadashiva (Trimurti), are near:", "options": ["Aurangabad", "Pune", "Mumbai", "Nashik"], "answer": 2, "explanation": "The Elephanta caves are on Gharapuri island in Mumbai harbour. Ajanta and Ellora are near Aurangabad.", "difficulty": "moderate", "source": "RRB NTPC · SSC CHSL"},
  {"id": "history-art-culture-53", "question": "Thrissur Pooram, a temple festival known for its caparisoned elephants and percussion, is celebrated in:", "options": ["Karnataka", "Tamil Nadu", "Kerala", "Goa"], "answer": 2, "explanation": "Thrissur Pooram is held at the Vadakkunnathan temple in Thrissur, Kerala; it was started by Sakthan Thampuran, ruler of Cochin.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-54", "question": "The invention of the sitar is traditionally attributed to:", "options": ["Tansen", "Amir Khusrau", "Baiju Bawra", "Swami Haridas"], "answer": 1, "explanation": "Tradition credits Amir Khusrau (13th–14th century) with the sitar and the tabla, though historians think the sitar took its modern form later. Tansen is linked with dhrupad.", "difficulty": "moderate", "source": "RRB NTPC · SSC CHSL"},
  {"id": "history-art-culture-55", "question": "The Mughal painter Ustad Mansur, given the title Nadir-ul-Asr by Jahangir, is best known for:", "options": ["Portraits of the emperor", "Paintings of birds, animals and flowers", "Illustrations of the Hamzanama", "Battle scenes of the Akbarnama"], "answer": 1, "explanation": "Mansur's studies of the Siberian crane, zebra, turkey cock and tulips reflect Jahangir's interest in natural history. The Hamzanama was illustrated earlier, under Akbar.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-56", "question": "The Hamzanama, a huge illustrated manuscript of the adventures of Amir Hamza, was produced under:", "options": ["Babur", "Humayun", "Akbar", "Shah Jahan"], "answer": 2, "explanation": "The Hamzanama (about 1,400 large paintings) was made in Akbar's atelier under Mir Sayyid Ali and Abd-us-Samad, who had come with Humayun from Persia.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-57", "question": "Basohli painting, with bold colours and beetle-wing decoration, is an early school of:", "options": ["Rajasthani painting", "Pahari painting", "Deccani painting", "Mughal painting"], "answer": 1, "explanation": "Basohli (in Kathua district of Jammu and Kashmir) is one of the earliest Pahari schools; Guler and Kangra developed later in the same hills.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-58", "question": "'Bani Thani', called the 'Mona Lisa of India', is a masterpiece of which school of painting?", "options": ["Kishangarh", "Mewar", "Bundi", "Kangra"], "answer": 0, "explanation": "Bani Thani was painted by Nihal Chand at Kishangarh under Raja Sawant Singh around 1750; the school is known for its elongated faces and almond eyes.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-59", "question": "Mudiyettu, a ritual dance-drama on the battle between goddess Kali and the demon Darika, is on UNESCO's Intangible Heritage list. It belongs to:", "options": ["Kerala", "Karnataka", "Tamil Nadu", "Odisha"], "answer": 0, "explanation": "Mudiyettu of Kerala was inscribed in 2010. Kerala's Kutiyattam was inscribed earlier, among the first proclamations of 2001.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-art-culture-60", "question": "Most of the polished Ashokan pillars were carved from sandstone quarried at:", "options": ["Mathura", "Chunar", "Sanchi", "Amaravati"], "answer": 1, "explanation": "The Mauryan pillars were made of buff Chunar sandstone (near Varanasi) and given a mirror-like polish. Mathura's red sandstone was used later by the Kushana sculptors.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-61", "question": "The Mathura school of sculpture typically used:", "options": ["Grey-blue schist", "White marble", "Spotted red sandstone", "Black basalt"], "answer": 2, "explanation": "Mathura sculptors used spotted red sandstone. Grey schist is typical of Gandhara and white limestone (often called marble) of Amaravati.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-62", "question": "The Amaravati school of sculpture flourished mainly under the patronage of the:", "options": ["Kushanas", "Guptas", "Satavahanas and Ikshvakus", "Pallavas"], "answer": 2, "explanation": "Amaravati in the Krishna valley flourished under the Satavahanas and later the Ikshvakus; its narrative reliefs in white limestone are noted for movement.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-63", "question": "The richly carved Hoysala temples at Belur and Halebidu are built mainly of:", "options": ["Granite", "Soapstone (chloritic schist)", "Red sandstone", "Laterite"], "answer": 1, "explanation": "Soft soapstone allowed the Hoysala craftsmen to carve extremely fine detail; the stone hardens on exposure to air.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-64", "question": "The Jantar Mantar observatories at Delhi, Jaipur, Ujjain, Varanasi and Mathura were built by:", "options": ["Raja Man Singh", "Sawai Jai Singh II", "Maharaja Ranjit Singh", "Raja Todar Mal"], "answer": 1, "explanation": "Sawai Jai Singh II of Amber, founder of Jaipur, built the five observatories in the early 18th century. The Jaipur Jantar Mantar is a World Heritage Site.", "difficulty": "hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-art-culture-65", "question": "Kalbelia, the folk dance and song form inscribed by UNESCO in 2010, is associated with:", "options": ["A snake-charmer community of Rajasthan", "Fisherfolk of Goa", "Tea-garden workers of Assam", "Tribal hunters of Odisha"], "answer": 0, "explanation": "The Kalbelias were traditionally snake charmers; their swirling black costumes recall a serpent. Ghoomar is a different Rajasthani dance.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-art-culture-66", "question": "The charbagh (four-part) garden layout was first used on a grand scale for a mausoleum in India at:", "options": ["Taj Mahal", "Tomb of Itimad-ud-Daulah", "Humayun's Tomb", "Akbar's tomb at Sikandra"], "answer": 2, "explanation": "Humayun's Tomb (1565–72), built by his widow Bega Begum, was the first great garden-tomb of the subcontinent and a model for the Taj Mahal.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-67", "question": "The Mughal building where pietra dura (inlay of semi-precious stones in marble) was first used extensively is:", "options": ["Humayun's Tomb", "Tomb of Itimad-ud-Daulah, Agra", "Buland Darwaza", "Red Fort, Delhi"], "answer": 1, "explanation": "Nur Jahan's tomb for her father Itimad-ud-Daulah (1622–28), the 'Baby Taj', marks the change from red sandstone to white marble with pietra dura.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-68", "question": "Match the folk dance with its state: A. Lavani B. Dollu Kunitha C. Bihu D. Ghoomar — 1. Rajasthan 2. Assam 3. Karnataka 4. Maharashtra", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Lavani – Maharashtra; Dollu Kunitha (drum dance of the Kurubas) – Karnataka; Bihu – Assam; Ghoomar – Rajasthan.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-69", "question": "Match the puppet tradition with its state: A. Kathputli B. Bommalattam C. Tholu Bommalata D. Putul Nach — 1. West Bengal 2. Andhra Pradesh 3. Tamil Nadu 4. Rajasthan", "options": ["A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 1, "explanation": "Kathputli (string) – Rajasthan; Bommalattam (string and rod) – Tamil Nadu; Tholu Bommalata (leather shadow) – Andhra Pradesh; Putul Nach (rod) – West Bengal.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-70", "question": "Arrange these Mughal buildings by when they were built: 1. Taj Mahal 2. Humayun's Tomb 3. Buland Darwaza 4. Tomb of Itimad-ud-Daulah", "options": ["2-4-3-1", "3-2-4-1", "2-3-4-1", "2-3-1-4"], "answer": 2, "explanation": "Humayun's Tomb 1565–72; Buland Darwaza c. 1575; Itimad-ud-Daulah 1622–28; Taj Mahal 1632–53.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-71", "question": "How many of these statements about the Ajanta caves are correct? I. They are Buddhist caves. II. Several of the later caves and paintings date from the Vakataka period. III. They are in Odisha. IV. Their paintings mostly show the lives of the Jain Tirthankaras.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. Ajanta is in Maharashtra, and its paintings mostly illustrate the Jataka stories and the life of the Buddha.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-72", "question": "Match the Hindustani gharana with the musician most associated with it: A. Kirana B. Gwalior C. Jaipur-Atrauli D. Agra — 1. Alladiya Khan 2. Faiyaz Khan 3. Abdul Karim Khan 4. Haddu and Hassu Khan", "options": ["A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-3, B-1, C-4, D-2"], "answer": 0, "explanation": "Kirana – Abdul Karim Khan; Gwalior, the oldest khayal gharana – Haddu and Hassu Khan; Jaipur-Atrauli – Alladiya Khan; Agra – Faiyaz Khan ('Aftab-e-Mausiqi').", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-73", "question": "Assertion (A): Mughal painting reached its height under Jahangir. Reason (R): Jahangir was a keen connoisseur who claimed he could name the artist of any painting at sight.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: Jahangir's personal taste drove the move to portraiture and natural history, with masters like Abul Hasan, Mansur and Bishandas.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-74", "question": "Assertion (A): Temples in the Dravida style have tall gateways called gopurams. Reason (R): Temples in the Nagara style have a curvilinear shikhara topped by an amalaka.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 1, "explanation": "Both statements are true, but the features of the Nagara style do not explain why Dravida temples have gopurams.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-75", "question": "Which pair of dancer and dance form is NOT correctly matched?", "options": ["Birju Maharaj — Kathak", "Kelucharan Mohapatra — Odissi", "Kalamandalam Gopi — Manipuri", "Guru Bipin Singh — Manipuri"], "answer": 2, "explanation": "Kalamandalam Gopi is a Kathakali exponent from Kerala. Guru Bipin Singh is regarded as the father of modern Manipuri dance.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-76", "question": "How many of these statements about rock-cut architecture are correct? I. Ashoka gave the Barabar caves to the Ajivikas. II. The great chaitya at Karla is in Maharashtra. III. The Udayagiri–Khandagiri caves of Odisha are Jain caves linked with Kharavela. IV. The Elephanta caves are Buddhist.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The Elephanta caves are mainly Shaiva, with the Sadashiva and the Ardhanarishvara panels.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-77", "question": "Arrange these temples by when they were built: 1. Lingaraja temple, Bhubaneswar 2. Shore Temple, Mamallapuram 3. Sun Temple, Konark 4. Kailasa temple, Ellora", "options": ["2-4-3-1", "4-2-1-3", "2-1-4-3", "2-4-1-3"], "answer": 3, "explanation": "Shore Temple c. 700–728 (Pallava); Kailasa c. 760s (Rashtrakuta); Lingaraja 11th century (Somavamshi/Ganga); Konark c. 1250 (Eastern Ganga).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-78", "question": "Match the World Heritage Site with its state: A. Group of Monuments at Hampi B. Champaner-Pavagadh C. Manas Wildlife Sanctuary D. Rock Shelters of Bhimbetka — 1. Madhya Pradesh 2. Assam 3. Gujarat 4. Karnataka", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Hampi – Karnataka; Champaner-Pavagadh – Gujarat; Manas – Assam; Bhimbetka – Madhya Pradesh.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-art-culture-79", "question": "How many of these are on UNESCO's list of the Intangible Cultural Heritage of Humanity? Tradition of Vedic chanting, Navroz, Chhau dance, Kathakali", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "Vedic chanting (2008), Navroz (2016, a multinational listing including India) and Chhau (2010) are listed. Kathakali is not; Kerala's listed forms are Kutiyattam and Mudiyettu.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-80", "question": "Assertion (A): The Sun Temple at Konark is also called the Black Pagoda. Reason (R): It is built in the Dravida style.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 2, "explanation": "A is true: European sailors called it the Black Pagoda. R is false: Konark is in the Kalinga variety of the Nagara style.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-81", "question": "Which one of the following is NOT among the classical dance forms recognised by the Sangeet Natak Akademi?", "options": ["Kathak", "Sattriya", "Yakshagana", "Mohiniyattam"], "answer": 2, "explanation": "Yakshagana is a traditional theatre form of Karnataka. The eight recognised forms are Bharatanatyam, Kathak, Kathakali, Kuchipudi, Manipuri, Mohiniyattam, Odissi and Sattriya.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-82", "question": "Match the Mughal monument with its location: A. Bibi ka Maqbara B. Shalimar Bagh (Jahangir) C. Jama Masjid (Shah Jahan) D. Tomb of Akbar — 1. Sikandra 2. Delhi 3. Srinagar 4. Aurangabad", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Bibi ka Maqbara (Aurangzeb's son, for his mother) – Aurangabad; Jahangir's Shalimar Bagh – Srinagar; Shah Jahan's Jama Masjid – Delhi; Akbar's tomb – Sikandra near Agra.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-83", "question": "How many of these statements about Kathak are correct? I. Its main gharanas are Lucknow, Jaipur and Banaras. II. Fast spins (chakkars) are a feature of the dance. III. It developed mainly in the temples of Odisha. IV. Birju Maharaj belonged to the Jaipur gharana.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. Kathak grew from north Indian kathakars and the Mughal and Awadh courts (Odissi is the Odisha form), and Birju Maharaj was of the Lucknow gharana.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-84", "question": "Arrange these treatises on music in chronological order: 1. Natyashastra 2. Sangita Ratnakara 3. Brihaddeshi 4. Sangita Parijata", "options": ["1-2-3-4", "1-3-2-4", "3-1-2-4", "1-3-4-2"], "answer": 1, "explanation": "Bharata's Natyashastra (c. 2nd century BCE–2nd century CE); Matanga's Brihaddeshi (c. 9th century); Sarangadeva's Sangita Ratnakara (13th century); Ahobala's Sangita Parijata (17th century).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-85", "question": "Which pair of textile and state is NOT correctly matched?", "options": ["Pashmina — Jammu and Kashmir", "Pochampally ikat — Telangana", "Chanderi — Madhya Pradesh", "Kanjeevaram silk — Kerala"], "answer": 3, "explanation": "Kanjeevaram (Kanchipuram) silk is from Tamil Nadu. The other pairs are correct, and all four are GI-tagged.", "difficulty": "very-hard", "source": "SSC CGL · State PSCs"},
  {"id": "history-art-culture-86", "question": "Kalaripayattu, one of the oldest martial arts of India, belongs to:", "options": ["Kerala", "Punjab", "Manipur", "Tamil Nadu"], "answer": 0, "explanation": "Kalaripayattu is from Kerala. Gatka is Punjabi, Thang-ta Manipuri and Silambam Tamil.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "history-art-culture-87", "question": "The Hemis festival, with masked cham dances honouring Guru Padmasambhava, is celebrated in:", "options": ["Sikkim", "Arunachal Pradesh", "Ladakh", "Himachal Pradesh"], "answer": 2, "explanation": "The festival is held at Hemis monastery near Leh, Ladakh. Losoong is a Sikkimese festival.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-88", "question": "Bathukamma, a floral festival celebrated by women, is a state festival of:", "options": ["Karnataka", "Odisha", "Kerala", "Telangana"], "answer": 3, "explanation": "Bathukamma, in which women arrange flowers in conical stacks and sing around them, is Telangana's state festival.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-89", "question": "Kerala Kalamandalam, which revived Kathakali and other Kerala art forms, was founded in 1930 by the poet:", "options": ["Kumaran Asan", "Vallathol Narayana Menon", "Ulloor S. Parameswara Iyer", "Kunchan Nambiar"], "answer": 1, "explanation": "Vallathol set up Kalamandalam, now a deemed university at Cheruthuruthy. Kunchan Nambiar was an 18th-century poet who created Ottan Thullal.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-art-culture-90", "question": "In Kuchipudi, the item called Tarangam is notable because the dancer:", "options": ["Wears a mask throughout", "Dances on the rim of a brass plate", "Performs in total silence", "Sings and plays the mridangam at once"], "answer": 1, "explanation": "In Tarangam the dancer balances on the edges of a brass plate, sometimes with a pot of water on the head, a signature Kuchipudi feat.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-art-culture-91", "question": "The Sangai Festival, named after the brow-antlered deer, is held every November in:", "options": ["Manipur", "Mizoram", "Tripura", "Meghalaya"], "answer": 0, "explanation": "Manipur's tourism festival is named after the Sangai, the State animal found in Keibul Lamjao National Park.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "history-art-culture-92", "question": "The Sun Temple at Modhera, built under the Solanki (Chaulukya) ruler Bhima I, is in:", "options": ["Rajasthan", "Odisha", "Gujarat", "Madhya Pradesh"], "answer": 2, "explanation": "Modhera, in Mehsana district of Gujarat, has a stepped tank (Surya Kund) in front of the temple. The Konark Sun Temple is in Odisha.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-art-culture-93", "question": "Ottan Thullal, a satirical solo performance art of Kerala, was created by:", "options": ["Kunchan Nambiar", "Vallathol Narayana Menon", "Swathi Thirunal", "Thunchath Ezhuthachan"], "answer": 0, "explanation": "Kunchan Nambiar created Ottan Thullal in the 18th century, using simple Malayalam and humour. Swathi Thirunal was a composer-king of Travancore.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-art-culture-94", "question": "The famous stone chariot (ratha) shrine of Garuda stands in the courtyard of which temple at Hampi?", "options": ["Virupaksha temple", "Hazara Rama temple", "Achyutaraya temple", "Vitthala temple"], "answer": 3, "explanation": "The stone chariot is in the Vitthala temple complex, also known for its musical pillars. The Virupaksha temple is Hampi's main living temple.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "history-art-culture-95", "question": "The monolithic Pancha Rathas at Mamallapuram were carved under the Pallava king:", "options": ["Mahendravarman I", "Narasimhavarman I", "Narasimhavarman II", "Nandivarman II"], "answer": 1, "explanation": "Narasimhavarman I “Mamalla” (7th century) is credited with the rathas, and the town is named after him. The structural Shore Temple came under Narasimhavarman II.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-art-culture-96", "question": "The Virupaksha temple at Pattadakal was built to commemorate a victory over the Pallavas by:", "options": ["Pulakeshin II", "Rajaraja I", "Queen Lokamahadevi, wife of Vikramaditya II", "Krishna I"], "answer": 2, "explanation": "Lokamahadevi had the temple built after Vikramaditya II's victory at Kanchipuram (8th century); it shows influence of the Kailasanatha temple there.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-97", "question": "The present Jagannath temple at Puri was begun by the Eastern Ganga ruler:", "options": ["Narasimhadeva I", "Kapilendra Deva", "Anantavarman Chodaganga", "Prataparudra Deva"], "answer": 2, "explanation": "Anantavarman Chodaganga (12th century) began it. Narasimhadeva I, a later Eastern Ganga king, built the Konark Sun Temple in the 13th century.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-art-culture-98", "question": "Which is regarded as the largest and best-preserved rock-cut chaitya hall in India?", "options": ["Karla (Karle)", "Bhaja", "Kanheri", "Ajanta Cave 26"], "answer": 0, "explanation": "The Karla chaitya near Lonavala, of the 1st century CE, has a high vaulted roof and a wooden umbrella over the stupa. Bhaja is an earlier, smaller chaitya.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-99", "question": "The scheme of 72 melakarta (parent) ragas of Carnatic music was set out in the 17th century by:", "options": ["Purandaradasa", "Tyagaraja", "Sarngadeva", "Venkatamakhin"], "answer": 3, "explanation": "Venkatamakhin's Chaturdandi Prakashika laid down the 72-melakarta system. Sarngadeva wrote the 13th-century Sangita Ratnakara.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-100", "question": "Tappa, a light classical vocal form with quick, knotted phrases, was developed from the songs of Punjabi camel drivers by:", "options": ["Shori Miyan", "Sadarang", "Tansen", "Baiju Bawra"], "answer": 0, "explanation": "Ghulam Nabi “Shori Miyan” refined tappa in the 18th century. Sadarang is linked to the development of khayal at Muhammad Shah's court.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-101", "question": "Thumri, the semi-classical form centred on romantic and devotional themes, flourished especially at the court of:", "options": ["Sawai Jai Singh at Jaipur", "Wajid Ali Shah at Lucknow", "Tipu Sultan at Srirangapatna", "Ranjit Singh at Lahore"], "answer": 1, "explanation": "The last Nawab of Awadh, Wajid Ali Shah, patronised thumri and Kathak in 19th-century Lucknow.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-102", "question": "Ramman, a religious festival and ritual theatre inscribed by UNESCO in 2009, belongs to:", "options": ["Himachal Pradesh", "Uttarakhand", "Sikkim", "Jammu and Kashmir"], "answer": 1, "explanation": "Ramman is performed in the Garhwal villages of Saloor-Dungra in Uttarakhand, in honour of the local deity Bhumiyal Devta.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-103", "question": "Pithora painting, done on house walls to invoke the deity Baba Pithora, is a ritual art of the:", "options": ["Gonds of Madhya Pradesh", "Warlis of Maharashtra", "Santhals of Jharkhand", "Rathwa and Bhil communities of Gujarat"], "answer": 3, "explanation": "Pithora paintings come mainly from the Rathwas and Bhils of central Gujarat and adjoining Madhya Pradesh. Warli art uses white stick figures; Gond art uses dots and lines.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-104", "question": "The Airavatesvara temple at Darasuram, one of the Great Living Chola Temples, was built by:", "options": ["Rajaraja I", "Rajendra I", "Kulottunga I", "Rajaraja II"], "answer": 3, "explanation": "Rajaraja II built Darasuram in the 12th century. Rajaraja I built the Brihadeeswara at Thanjavur and Rajendra I the temple at Gangaikondacholapuram.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-105", "question": "Match the exponent with the dance form: A. Kelucharan Mohapatra B. Guru Bipin Singh C. Kalamandalam Kalyanikutty Amma D. Birju Maharaj — 1. Kathak 2. Mohiniyattam 3. Manipuri 4. Odissi", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Kelucharan Mohapatra revived Odissi, Guru Bipin Singh shaped modern Manipuri, Kalyanikutty Amma revived Mohiniyattam and Birju Maharaj led the Lucknow gharana of Kathak.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-art-culture-106", "question": "Match the painting tradition with its state: A. Cheriyal scrolls B. Saura (Idital) C. Sohrai D. Kalighat — 1. West Bengal 2. Jharkhand 3. Odisha 4. Telangana", "options": ["A-4, B-2, C-3, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Cheriyal narrative scrolls come from Telangana, Saura wall paintings from Odisha, Sohrai mural art from Hazaribagh in Jharkhand and Kalighat pat paintings from Kolkata.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-107", "question": "In the Kalinga (Odisha) style of temple architecture, the “jagamohana” is the:", "options": ["Sanctum housing the deity", "Assembly or porch hall in front of the sanctum", "Hall of offerings at the far end", "Crowning ribbed stone disc"], "answer": 1, "explanation": "An Odisha temple typically has the deul (sanctum with tower), jagamohana (assembly hall), nata mandira (dance hall) and bhoga mandapa (offering hall). The ribbed disc is the amalaka.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-108", "question": "Match the part of a stupa with its description: A. Anda B. Harmika C. Medhi D. Torana — 1. Ornamental gateway 2. Hemispherical dome 3. Raised terrace or base used for circumambulation 4. Railed square platform on top of the dome", "options": ["A-2, B-4, C-3, D-1", "A-2, B-3, C-4, D-1", "A-4, B-2, C-3, D-1", "A-2, B-4, C-1, D-3"], "answer": 0, "explanation": "The anda is the dome, the harmika the railed balcony from which the chhatra rises, the medhi the raised terrace, and the toranas the carved gateways, as at Sanchi.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-109", "question": "Match the folk theatre with its state: A. Jatra B. Tamasha C. Bhavai D. Nautanki — 1. Uttar Pradesh 2. Gujarat 3. Maharashtra 4. West Bengal", "options": ["A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 1, "explanation": "Jatra is Bengali open-air theatre, Tamasha is Marathi, Bhavai is from Gujarat and Nautanki from Uttar Pradesh.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-art-culture-110", "question": "Consider the following statements: 1. Pattadakal has temples in both the Nagara and the Dravida styles. 2. Pattadakal is a UNESCO World Heritage Site. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. The Chalukyan temples at Pattadakal, such as the Papanatha (Nagara) and Virupaksha (Dravida), were inscribed in 1987.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-111", "question": "How many of these temples are part of the UNESCO site “Great Living Chola Temples”? Brihadeeswara at Thanjavur, Brihadeeswara at Gangaikondacholapuram, Airavatesvara at Darasuram, Meenakshi at Madurai", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "The first three are Chola temples inscribed under this site. The Meenakshi temple at Madurai is largely of the Nayaka period and is not part of it.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-112", "question": "Arrange these Indian elements in the order in which they were added to UNESCO's Intangible Cultural Heritage list: 1. Kutiyattam 2. Ramman 3. Sankirtana of Manipur 4. Garba of Gujarat", "options": ["1, 2, 3, 4", "2, 1, 3, 4", "1, 3, 2, 4", "1, 2, 4, 3"], "answer": 0, "explanation": "Kutiyattam was among the first (proclaimed in 2001), Ramman was inscribed in 2009, Sankirtana in 2013 and Garba in 2023.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-113", "question": "Match the martial art with its state: A. Gatka B. Thang-ta C. Silambam D. Mardani Khel — 1. Maharashtra 2. Tamil Nadu 3. Manipur 4. Punjab", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1"], "answer": 2, "explanation": "Gatka is the Sikh art of stick and sword, Thang-ta the Manipuri art of sword and spear, Silambam a Tamil staff art and Mardani Khel a Maratha weapon art.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "history-art-culture-114", "question": "Assertion (A): The Dilwara and Ranakpur temples are celebrated for their intricate marble carving. Reason (R): Both temple complexes are in Rajasthan.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 1, "explanation": "Both are true, but location does not explain the carving. The fine work reflects rich Jain patrons such as Vimal Shah and Dharna Shah and skilled sompura craftsmen.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "history-art-culture-115", "question": "Match the building with its architect: A. Victoria Memorial, Kolkata B. Rashtrapati Bhavan, New Delhi C. Gateway of India, Mumbai D. Capitol Complex, Chandigarh — 1. William Emerson 2. George Wittet 3. Le Corbusier 4. Edwin Lutyens", "options": ["A-1, B-4, C-3, D-2", "A-4, B-1, C-2, D-3", "A-1, B-4, C-2, D-3", "A-2, B-4, C-1, D-3"], "answer": 2, "explanation": "Emerson designed the Victoria Memorial, Lutyens the Viceroy's House (now Rashtrapati Bhavan), Wittet the Gateway of India, and Le Corbusier the Capitol Complex, a World Heritage Site since 2016.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
];

